const data={barrel:['Barrel & mainspring','위쪽 · 무브먼트 면','태엽의 안쪽 끝은 중심축의 갈고리에, 바깥쪽 끝은 통 안쪽의 걸림부에 연결됩니다. 감을 때는 축을 돌려 금속 띠를 휘게 합니다. 놓으면 초록 래칫 클릭이 축의 역회전을 막고, 태엽이 펴지려는 힘은 바깥 고정부를 통해 회전 가능한 통을 돌립니다. 접착제가 아니라 기계적인 연결입니다. 덮개를 열어 파란 중심과 주황색 바깥 고정부를 비교하세요.','연결','용두로 감고 → 통에서 힘을 꺼냅니다'],center:['Center wheel & pinion','중앙 · 다이얼로 이어지는 축','긴 축이 지판을 관통합니다. 무브먼트 면에서는 기어열을, 다이얼 면에서는 캐넌 피니언과 분침을 구동합니다.','회전','1시간에 1회전'],third:['Third wheel & pinion','중앙의 왼쪽 · 중간 기어','아래의 작은 피니언은 센터 휠과 맞물립니다. 같은 축의 큰 휠은 한 층 위에서 4번 휠의 피니언을 돌립니다.','연결','센터에서 받아 → 4번 휠로 전달'],fourth:['Fourth wheel & pinion','중앙 아래쪽 · 탈진기로 연결','3번 휠에서 동력을 받아 1분에 한 번 회전합니다. 위쪽 휠은 이스케이프 피니언과 맞물립니다. 이 축 위의 추가 기어가 중간 기어를 거쳐 중앙 초침축을 돌립니다.','회전','1분에 1회전'],escape:['Escape wheel & pinion','아래 왼쪽 · 밸런스 옆','작은 피니언은 4번 휠에서 힘을 받고, 위쪽 15개 이는 팔렛과 번갈아 접촉합니다. 잠금·충격면의 정밀 치형은 단순화했습니다.','전진','해제당 반 잇수 · 12°'],fork:['Pallet fork','이스케이프 휠과 밸런스 사이','두 팔렛이 휠을 번갈아 잠그고, 반대편 포크가 밸런스의 롤러 쥬얼과 작용합니다. 기어열의 에너지를 진동계에 전달하는 위치입니다.','역할','잠금 · 해제 · 충격 전달'],balance:['Balance & hairspring','아래쪽 · 가장 큰 진동 공간','밸런스가 왕복할 공간을 가장자리 쪽에 확보합니다. 헤어스프링의 바깥 끝은 고정되고 안쪽은 밸런스 축과 움직입니다.','기준','4 Hz · 초당 8회 해제'],motion:['Motion works','지판 반대편 · 다이얼 아래','센터 축의 회전이 먼저 분침을 돌립니다. 옆의 중간 기어를 한 번 돌아오는 길을 거치면 회전이 느려져 시침을 돌립니다. 분침이 한 바퀴 도는 동안 시침은 다음 숫자까지 한 칸 움직입니다.','기어비','분침 한 바퀴 → 시침 한 칸'],hands:['Dial & coaxial hands','중앙의 시침·분침·초침','파란 분침과 금색 시침은 중앙에 포개져 있지만 속도가 다릅니다. 초록색 초침은 별도 전달 기어가 돌리는 중앙 축에 달려 있습니다. 위의 시간 슬라이더로 세 바늘을 함께 움직여 보세요.','방향','다이얼 면에서 시계 방향']};
Object.assign(names,{crown:'용두·감기 축',keyless:'연결 전환·시간 맞춤 기구',seconds:'초침 전달 기어·중앙 축',automatic:'로터·오토매틱 감기',calendar:'날짜판·날짜 구동 기구',gmt:'GMT·24시간 바늘',moon:'문페이즈·달판',chronograph:'크로노그래프·클러치·리셋'});
Object.assign(levels,{crown:0,keyless:0,seconds:4,automatic:4,calendar:4,gmt:4,moon:4,chronograph:4});
Object.assign(data,{gmt:['GMT / second time zone','다이얼 아래 · 24시간 휠','시침의 회전을 절반으로 줄여 하루에 한 번 도는 바늘을 추가합니다.','주기','24시간에 한 바퀴'],moon:['Moon phase','다이얼 아래 · 59치 달판','하루 한 칸씩 달판을 돌리고 표시창이 달의 일부를 가립니다.','주기','59칸 · 두 달 · 29.5일'],
 crown:['Crown & stem','오른쪽 · 손의 입력','용두를 돌리거나 당겨 감기·날짜·시간 조정 경로를 선택합니다. 회전하는 감기 축과 움직이는 연결 부품을 구분해 보세요.','세 위치','0 감기 · 1 날짜 · 2 시간'],
 keyless:['Keyless works','용두 안쪽 · 연결 전환','용두를 당기면 레버와 연결 부품이 움직여 감기, 날짜 조정, 시간 맞춤 중 한 경로를 선택합니다. 시간 맞춤 전달축 아래 기어는 분 휠과 맞물리는 데 필요합니다. 초침을 중앙으로 옮겨도 이 기어는 남습니다.','시간 조정','전달축 → 분 휠 → 시침·분침'],
 seconds:['Indirect central seconds','4번 휠 위 → 중앙 관통축','4번 휠에 고정된 전달 기어가 중간 기어를 거쳐 중앙 초침축을 돌립니다. 시간 맞춤 기어와는 별도 경로입니다. 확대 뷰도 같은 잇수·중심 위치를 사용합니다.','회전','정방향 → 역방향 → 정방향 · 1분 1회전'],
 automatic:['Automatic winding','무브먼트 뒤쪽 · 로터','로터의 양방향 회전을 방향 전환 장치에서 한 방향으로 모으고 감속하여 태엽을 감습니다. 감김 상태는 기본 모델의 태엽과 공유합니다.','에너지','손목 운동 → 로터 → 태엽'],
 calendar:['Simple date calendar','다이얼 아래 · 31칸 날짜판','12시간마다 도는 시침 쪽에서 받아 24시간 바퀴를 돌립니다. 핑거가 하루에 한 칸 밀고 점퍼가 정렬합니다. 용두 첫 번째 당김 위치는 빠른 날짜 조정입니다.','주기','24시간에 한 칸 · 31 다음 1'],
 chronograph:['Seiko 6139A chronograph','컬럼 휠 · 수직 클러치 · 회전 해머','푸셔가 컬럼 휠을 한 칸 돌려 두 결합 레버를 여닫습니다. 클러치 스프링이 동력을 연결하고, 정지 후 복귀 레버가 회전 해머로 두 하트캠을 영점에 맞춥니다.','측정','중앙 측정 초침 · 30분 누적계']});
for(const k of ['crown','keyless','seconds','automatic','calendar','gmt','moon','chronograph']){const b=document.createElement('button');b.className='part';b.dataset.part=k;b.innerHTML='<i class="swatch" style="--c:#19896c"></i>'+names[k]+'<span class="arrow">↗</span>';document.querySelector('.partlist').append(b);}
for(const g of [slidingClutch,selectorLever,settingBridge])g.traverse(m=>{if(m.isMesh)m.userData.key='keyless';});
// Cache original materials so repeated selections never accumulate tint.
const selectionBlue=new T.Color(0x148fc5),contextGrey=new T.Color(0xa3acb6);
function highlight(key){
 for(const m of meshes){
  const mat=m.material;
  if(!m.userData.baseMaterial)m.userData.baseMaterial={color:mat.color.clone(),metalness:mat.metalness,roughness:mat.roughness};
  const base=m.userData.baseMaterial,active=m.userData.key===key;
  mat.color.copy(base.color);mat.metalness=base.metalness;mat.roughness=base.roughness;mat.emissive.setHex(0);mat.emissiveIntensity=0;mat.opacity=1;mat.transparent=false;mat.depthWrite=true;
  if(active){mat.color.copy(m.userData.pathColor?new T.Color(m.userData.pathColor):m.userData.jewel?new T.Color(0xe53b72):m===dial?new T.Color(0xd9edf7):selectionBlue);mat.metalness=.22;mat.roughness=.42;mat.emissive.setHex(0x006b9e);mat.emissiveIntensity=m===dial?.06:.35;}
  else if(m.userData.key in names)mat.color.lerp(contextGrey,.25);
  if(active&&m.geometry!==sg&&!m.userData.selectionOutline){
   const line=new T.LineSegments(new T.EdgesGeometry(m.geometry,40),new T.LineBasicMaterial({color:0x064b70,transparent:true,opacity:.85,depthTest:true,depthWrite:false}));
   line.raycast=()=>{};m.add(line);m.userData.selectionOutline=line;
  }
  if(m.userData.selectionOutline)m.userData.selectionOutline.visible=active;
 }
 hairLine.material.color.setHex(key==='balance'?0x009fd7:0x385875);
}
function choose(k){if(advanced&&ADVANCED_MODES.includes(k)){inspectAdvanced(k);return;}if(!(k in names)||levels[k]>step)return;selected=k;const d=data[k];$('partTitle').textContent=names[k];['partEng','partTag','partDesc','specLabel','specValue'].forEach((id,i)=>$(id).textContent=d[i]);document.querySelectorAll('[data-part]').forEach(b=>{b.classList.toggle('active',b.dataset.part===k);b.setAttribute('aria-pressed',b.dataset.part===k);});highlight(k);showPartLesson(k,names[k]);$('locationChip').textContent=names[k]+' · '+d[1];}
function setView(v,explicit=false){if(!explicit)return;view=v;orbit.preset(v);$('rear').setAttribute('aria-pressed',v==='rear');$('dialView').setAttribute('aria-pressed',v==='dial');$('viewCaption').textContent=v==='rear'?'무브먼트 방향 · 자유 회전 가능':'다이얼 방향 · 자유 회전 가능';}

const titles=[['손으로 감아, 힘을 저장합니다.','먼저 용두를 돌려 보세요. 감기 기어가 태엽의 중심을 돌리고, 금속 띠에 힘이 저장됩니다.','태엽 감기'],['저장된 힘이 기어를 돌립니다.','태엽통 → 센터 → 3번 → 4번. 서로 닿는 큰 바퀴와 작은 바퀴를 따라가 보세요.','동력 전달'],['힘을 조금씩 풀어 줍니다.','팔렛 포크가 잡았다 놓아 주면, 연결된 기어들이 조금씩 전진합니다.','탈진기'],['왕복 운동이 박자를 정합니다.','밸런스가 돌아올 때마다 포크를 움직여 다음 한 걸음을 허용합니다.','진동계'],['세 바늘은 서로 다른 길로 움직입니다.','분침은 센터 축에서, 초침은 4번 휠에서, 시침은 더 느려지는 기어를 거쳐 움직입니다.','바늘 연결']];
const lessons=[['감는 동안과 풀리는 동안을 구분해 보세요.','용두는 태엽의 안쪽 끝을 감습니다. 저장한 힘을 꺼낼 때는 태엽의 바깥 끝이 통을 돌립니다.','움직임 전달하기 →'],['센터에서 길이 나뉩니다.','한쪽은 3번·4번 휠을 지나 박자를 조절하는 장치로, 다른 쪽은 지판 반대편의 분침과 시침으로 이어집니다.','탈진기 연결하기 →'],['잠금 → 해제 → 다시 잠금','태엽을 감은 뒤 한 번 해제를 눌러, 포크와 기어열이 함께 움직이는 모습을 보세요.','밸런스 연결하기 →'],['시계가 스스로 다음 걸음을 정합니다.','밸런스 핀이 포크 입구를 통과할 때마다 잠금이 풀립니다. 관찰 모드는 실제보다 8배 느립니다.','세 바늘 연결하기 →'],['분침 한 바퀴, 시침 한 칸.','위의 시간 슬라이더를 움직여 보세요. 중앙 초침은 1분마다 한 바퀴, 분침은 1시간마다 한 바퀴 돕니다.','처음부터 다시 보기 ↺']];
function setStep(n){if(n>=5){selectAdvanced(ADVANCED_MODES[n-5]);return;}courseChapter=n;document.body.classList.remove('advancedLesson');if($('advancedParts'))$('advancedParts').hidden=true;const storedOffset=handOffset;const storedCharge=charge,storedSeconds=seconds,storedBeats=beats;step=n;reset(false);seconds=smoothSeconds=storedSeconds;beats=storedBeats;handOffset=storedOffset;charge=storedCharge;windAngle=charge/100*TAU*5.625;routeFocus=n===4?3:0;const d=titles[n];$('pageTitle').textContent=d[0];$('pageSub').textContent=d[1];$('chapter').textContent='0'+(n+1)+' / 08 · '+d[2];document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',+b.dataset.step===n);b.setAttribute('aria-current',+b.dataset.step===n?'step':'false');});document.querySelectorAll('[data-part]').forEach(b=>b.hidden=levels[b.dataset.part]>n||ADVANCED_MODES.includes(b.dataset.part));$('manualPanel').hidden=n!==1;$('springPanel').hidden=false;$('wind').hidden=false;$('tick').hidden=n!==2;$('rate').hidden=n<3;$('hour').hidden=n!==4;$('play').hidden=n===2||n===0;$('cover').disabled=false;$('bridges').disabled=n<3;$('openDial').disabled=n<4;$('dialView').disabled=n<4;$('bridges').checked=$('cover').checked=$('openDial').checked=false;$('lessonNo').textContent='0'+(n+1);$('lessonTitle').textContent=lessons[n][0];$('lessonText').textContent=lessons[n][1];$('next').textContent=n===4?'다음 · 오토매틱':lessons[n][2];$('gearReadings').hidden=n!==1;$('beatReadings').hidden=n<2;$('observeTitle').textContent=['用두 → 감기 기어 → 태엽 중심','태엽통 → 센터 → 3번 → 4번','잡고 → 놓고 → 다시 잡기','한 번 왕복 → 두 번 해제','초침 1분 · 분침 1시간 · 시침 12시간'][n].replace('用두','용두');$('observeText').textContent=n===4?'세 바늘은 중앙에 모이지만 초침의 회전은 별도 기어로 전달됩니다.':'위의 경로 버튼으로 연결을 하나씩 따라가세요.';rate=.125;$('rate').textContent='관찰 0.125×';$('experimentHint').textContent=n===0?'용두 버튼을 누르면 약 2.5초 동안 감깁니다. 파란 표시가 태엽의 중심입니다.':n===1?'태엽을 감고 풀어 보세요. 직접 돌려보기는 회전비를 보는 별도 실험입니다.':'태엽을 감은 뒤 작동하세요. 기본 관찰 속도는 8배 느립니다.';setView('rear');choose(['barrel','center','fork','balance','hands'][n]);window.watchJourney.setStep(n);sync();}
function reset(resetAdvanced=true){if(advanced){advanced.pauseInput();advanced.setView('none');}if(resetAdvanced&&advanced)advanced.reset();if(crownMode)setCrownMode(false);if(coaxMode)setCoaxMode(false);automaticWindPulse=0;crownInput=dateInputAngle=0;pendingDate=false;crownMessage='';crownPosition=0;handOffset=settingLeft=settingTurn=freeCrownTurn=freeTurnLeft=0;resumeAfterSetting=false;timeExperiment=false;windingLeft=handDemoLeft=0;routeFocus=step===4?3:0;seconds=smoothSeconds=beats=fraction=release=windAngle=0;forkShown=-.12;charge=0;playing=false;lastSpring='';readings();sync();}
function sync(){const empty=charge<=0;$('play').disabled=empty||crownPosition===2;$('play').textContent=playing?'일시 정지':empty?'먼저 태엽을 감으세요':step===0?'태엽 감기':step===1?'태엽 풀어 기어 돌리기':'시계 작동';$('play').setAttribute('aria-pressed',playing);$('wind').disabled=crownPosition!==0||charge+windingLeft>=100;$('tick').disabled=crownPosition===2||empty;$('hour').disabled=crownPosition===2||charge<100/45;$('manual').disabled=crownPosition===2;$('status').textContent=crownMode?(crownPosition===1?crownCorrection()+' 조정 · 용두에서 독립 보정 경로로 전달':crownPosition===2?'시간 맞춤: 용두 → 전달축 → 분 휠 → 두 바늘':'태엽 감기: 용두 → 감기 휠 → 태엽 중심'):coaxMode?'세 축·관의 절개 모형 · 파란 분침 1회전 = 금색 시침 1칸':crownPosition===2?'시간 맞춤 · 시침·분침만 조정 · 초침 정지':timeExperiment?'바늘 연결 실험 · 태엽 소모 없이 시간만 움직입니다':empty?'태엽을 감아 작동을 시작하세요':playing?'연결된 기어열이 동력을 전달합니다':step===2?'잠김 · 한 번 해제를 눌러 주세요':'부품을 선택해 위치와 연결을 살펴보세요';updateCrownUI();}
function readings(){const ca=seconds/3600;$('turnA').textContent=ca.toFixed(2);$('turnB').textContent=(-ca*8).toFixed(2);if(step===1){const d=ca*360,v=d>360?d%360:d;$('manual').value=Math.round(v);$('manualValue').textContent=Math.round(v)+'°';}$('charge').value=charge;$('chargeText').textContent=charge>0&&charge<1?'<1%':Math.round(charge)+'%';$('beatCount').textContent=beats.toLocaleString('ko-KR');$('lockState').textContent=timeExperiment?'바늘 속도 비교 중':release>0?'해제 · 충격 전달':'잠김';const whole=Math.floor(seconds+1e-6),h=Math.floor(whole/3600),m=Math.floor(whole/60)%60,s=whole%60;$('timeReading').textContent=step===2?'수동 전환 · 일정한 박자 없음':'모의 경과 '+[h,m,s].map(x=>String(x).padStart(2,'0')).join(':');$('hour').disabled=crownPosition===2||charge<100/45;}
function advance(n){const cost=100/(S.reserveSeconds*8),count=Math.min(n,Math.floor((charge+1e-10)/cost));beats+=count;seconds+=count/8;advanced?.advance(count/8);charge=Math.max(0,charge-count*cost);release=.18;if(charge<cost){charge=0;playing=false;}readings();sync();}
