function setCrownPosition(position){if(position===1&&!crownCorrection())position=2;if(position===crownPosition)return;const wasRunning=playing,wasSetting=crownPosition===2,keepRear=view==='rear',savedYaw=yaw,savedTilt=tilt,savedDistance=distance;crownPosition=position;if(position===1){dateInputAngle=0;correctionTravel=0;}pendingDate=false;crownMessage='';windingLeft=handDemoLeft=settingLeft=freeTurnLeft=0;timeExperiment=false;if(position===2){resumeAfterSetting=wasRunning;playing=false;if(!crownMode&&!advanced?.mode.includes('calendar')){setView('rear');if(keepRear){yaw=savedYaw;tilt=savedTilt;distance=savedDistance;}}}else if(wasSetting){playing=resumeAfterSetting&&charge>0;resumeAfterSetting=false;}sync();readings();}
