function turnCrown(direction){if(crownPosition===1){if(freeTurnLeft)return;correctionTravel=0;correctionDirection=direction;if(['gmt','moon'].includes(advanced?.mode)){const changed=advanced.correctComplication(direction);freeTurnLeft=-direction*TAU*1.5;crownMessage=changed?(advanced.mode==='gmt'?'용두 → 독립 조정 칼라 → GMT 바늘 한 시간 이동':'용두 → 달판 보정 → 59치 휠 한 칸 이동'):'역방향 공회전 · 달판은 그대로입니다.';sync();return;}if(direction<0){freeTurnLeft+=TAU*1.5;crownMessage='역방향: 용두와 조정축만 회전 · 조정 핑거는 물러나 날짜판은 그대로입니다.';}else if(advanced?.state.canQuickset()){pendingDate=true;freeTurnLeft-=TAU*1.5;crownMessage='정방향: 조정축 → 편심 핑거 → 날짜판 한 칸 → 점퍼 고정';}else crownMessage='21–03시에는 날짜 기구가 맞물려 있습니다. 아래 06:00 버튼으로 옮긴 뒤 조정하세요.';sync();return;}const action=S.crownAction(crownPosition,direction);if(crownPosition===2){settingLeft+=action.settingSeconds;routeFocus=3;}else if(action.windPercent)$('wind').click();else {freeTurnLeft+=TAU;crownMessage='역방향: 브레게 톱니가 미끄러져 감기 피니언은 정지합니다. 초록 클릭이 태엽의 역회전을 막습니다.';}if(action.windPercent)crownMessage='정방향: 파란 연결 톱니 → 감기 피니언 → 크라운 휠 → 중간 휠 → 태엽 중심';sync();}
