function setCoaxMode(enabled){if(enabled&&advanced){advanced.setView('none');$('handExperiment').hidden=false;}if(enabled&&crownMode)setCrownMode(false);if(enabled&&crownPosition===2)setCrownPosition(0);coaxMode=enabled;for(const id of ['secondDemo','handDemo'])$(id).hidden=enabled;root.visible=!enabled;coaxDemo.group.visible=enabled;$('coaxToggle').textContent=enabled?'전체 시계로 돌아가기':'세 바늘의 축·관 구조 확대';$('coaxToggle').setAttribute('aria-pressed',enabled);for(const id of ['coaxMinute','coaxHour','coaxSecond','coaxBoth','coaxRun','coaxSecondRun','coaxNote'])$(id).hidden=!enabled;if(enabled){playing=false;windingLeft=handDemoLeft=settingLeft=0;yaw=-.28;tilt=1.02;distance=13;flip=0;view='rear';setView('rear');yaw=-.28;tilt=1.02;$('viewCaption').textContent='세 축·관 확대 · 길이와 간격을 늘린 절개 모형';coaxDemo.setFocus('both');setCoaxFocus('both');$('partTitle').textContent='한 중심, 세 개의 회전';$('partEng').textContent='Coaxial seconds, minute & hour';$('partTag').textContent='중심은 초침 · 중간은 분침 · 바깥은 시침';$('specLabel').textContent='관찰';$('specValue').textContent='분침 한 바퀴 → 시침 한 칸';$('partDesc').textContent='초침은 가장 가는 초록 축에, 분침은 그 축을 감싸는 파란 관에, 시침은 바깥 금색 관에 붙습니다. 세 부품은 한 중심을 쓰지만 서로 고정되어 있지 않습니다. 왼쪽 3번 휠의 큰 바퀴가 4번 휠의 작은 피니언과 맞물립니다. 4번 휠과 초록 전달 기어는 같은 축에 고정되어 있습니다. 그 회전이 초록 중간 기어와 중앙 기어를 지나 초침축으로 이어집니다. 시침은 분침 쪽 감속 기어에서 힘을 받습니다.';$('locationChip').textContent='확대 절개 모형 · 두 관의 앞 절반을 제거했습니다';}else{target.set(0,0,0);distance=12.6;setView('dial');}sync();}
